-- JobTrack initial schema (MySQL 8.0.16+; also runs on H2 in MySQL mode for tests).
-- InnoDB and utf8mb4 are the MySQL 8 defaults, so no table options are needed.
-- Every id is a random UUID generated by the application and stored as CHAR(36); nothing auto-increments.

CREATE TABLE users (
    id              CHAR(36)     NOT NULL,
    email           VARCHAR(255) NOT NULL,
    password_hash   VARCHAR(100) NOT NULL,
    display_name    VARCHAR(100),
    role            VARCHAR(20)  NOT NULL,
    enabled         BOOLEAN      DEFAULT TRUE NOT NULL,
    created_at      DATETIME(6)  NOT NULL,
    last_login_at   DATETIME(6),
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_role CHECK (role IN ('USER', 'ADMIN'))
);

-- Rule 1: every application belongs to exactly one user (user_id NOT NULL; never updated by the app)
CREATE TABLE job_applications (
    id              CHAR(36)      NOT NULL,
    user_id         CHAR(36)      NOT NULL,
    company         VARCHAR(200)  NOT NULL,
    position_title  VARCHAR(200)  NOT NULL,
    location        VARCHAR(200),
    job_url         VARCHAR(1000),
    source          VARCHAR(100),
    status          VARCHAR(30)   DEFAULT 'SAVED' NOT NULL,
    applied_date    DATE,
    jd_text         MEDIUMTEXT,
    notes           TEXT,
    created_at      DATETIME(6)   NOT NULL,
    updated_at      DATETIME(6)   NOT NULL,
    version         BIGINT        DEFAULT 0 NOT NULL,
    CONSTRAINT pk_job_applications PRIMARY KEY (id),
    CONSTRAINT fk_app_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX idx_app_user_status ON job_applications (user_id, status);
CREATE INDEX idx_app_user_updated ON job_applications (user_id, updated_at);
CREATE INDEX idx_app_user_applied ON job_applications (user_id, applied_date);

-- Rules 2/3: status history; occurred_at = when it happened, recorded_at = when it was entered
CREATE TABLE status_history (
    id              CHAR(36)      NOT NULL,
    application_id  CHAR(36)      NOT NULL,
    from_status     VARCHAR(30),
    to_status       VARCHAR(30)   NOT NULL,
    occurred_at     DATETIME(6)   NOT NULL,
    recorded_at     DATETIME(6)   NOT NULL,
    note            VARCHAR(1000),
    changed_by      CHAR(36),
    CONSTRAINT pk_status_history PRIMARY KEY (id),
    CONSTRAINT fk_hist_app FOREIGN KEY (application_id) REFERENCES job_applications (id) ON DELETE CASCADE,
    CONSTRAINT fk_hist_user FOREIGN KEY (changed_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX idx_hist_app_occurred ON status_history (application_id, occurred_at);

-- Rule 4: unlimited interview rounds, but round numbers are unique per application
CREATE TABLE interviews (
    id               CHAR(36)      NOT NULL,
    application_id   CHAR(36)      NOT NULL,
    round_number     INT           NOT NULL,
    interview_type   VARCHAR(30)   NOT NULL,
    scheduled_at     DATETIME(6),
    duration_minutes INT,
    interviewer      VARCHAR(200),
    location         VARCHAR(500),
    outcome          VARCHAR(20)   DEFAULT 'PENDING' NOT NULL,
    notes            TEXT,
    created_at       DATETIME(6)   NOT NULL,
    updated_at       DATETIME(6)   NOT NULL,
    CONSTRAINT pk_interviews PRIMARY KEY (id),
    CONSTRAINT fk_iv_app FOREIGN KEY (application_id) REFERENCES job_applications (id) ON DELETE CASCADE,
    CONSTRAINT uk_iv_app_round UNIQUE (application_id, round_number),
    CONSTRAINT ck_iv_round CHECK (round_number >= 1)
);
CREATE INDEX idx_iv_scheduled ON interviews (scheduled_at);

-- Rules 5/6: documents (JD file / CV / cover letter / other); every upload is a new version, never an overwrite
CREATE TABLE documents (
    id                CHAR(36)      NOT NULL,
    application_id    CHAR(36)      NOT NULL,
    doc_type          VARCHAR(20)   NOT NULL,
    version_no        INT           NOT NULL,
    original_filename VARCHAR(255)  NOT NULL,
    stored_filename   VARCHAR(100)  NOT NULL,
    content_type      VARCHAR(100)  NOT NULL,
    size_bytes        BIGINT        NOT NULL,
    sha256            VARCHAR(64)   NOT NULL,
    uploaded_at       DATETIME(6)   NOT NULL,
    CONSTRAINT pk_documents PRIMARY KEY (id),
    CONSTRAINT fk_doc_app FOREIGN KEY (application_id) REFERENCES job_applications (id) ON DELETE CASCADE,
    CONSTRAINT uk_doc_version UNIQUE (application_id, doc_type, version_no),
    CONSTRAINT uk_doc_stored UNIQUE (stored_filename)
);

-- Interview question bank: each user's own collection of technical and behavioral questions,
-- independent of applications and interview rounds. Deleting a user deletes their questions.
-- A question is PRIVATE by default and can be made PUBLIC, which lists it in the interview hall.
-- The answer and self-rating are always private to the owner, whatever the visibility.
CREATE TABLE interview_questions (
    id             CHAR(36)      NOT NULL,
    user_id        CHAR(36)      NOT NULL,
    category       VARCHAR(20)   NOT NULL,
    question_text  TEXT          NOT NULL,
    answer_text    TEXT,
    self_rating    VARCHAR(10),
    visibility     VARCHAR(10)   DEFAULT 'PRIVATE' NOT NULL,
    published_at   DATETIME(6),
    created_at     DATETIME(6)   NOT NULL,
    updated_at     DATETIME(6)   NOT NULL,
    CONSTRAINT pk_interview_questions PRIMARY KEY (id),
    CONSTRAINT fk_q_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT ck_q_category CHECK (category IN ('TECHNICAL', 'BEHAVIORAL')),
    CONSTRAINT ck_q_rating CHECK (self_rating IS NULL OR self_rating IN ('GOOD', 'OK', 'POOR')),
    CONSTRAINT ck_q_visibility CHECK (visibility IN ('PRIVATE', 'PUBLIC'))
);
CREATE INDEX idx_q_user_category ON interview_questions (user_id, category, updated_at);
CREATE INDEX idx_q_public ON interview_questions (visibility, category, published_at);
